import{_ as a,o as r,c as l,a3 as o}from"./chunks/framework.BwzYn71E.js";const b=JSON.parse('{"title":"复杂串并行混产理论与实践研究","description":"","frontmatter":{"translationSource":{"title":"复杂串并行混产理论与实践研究","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=NHHXhzWI123bEmz73RliaL","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/research-on-theory-and-practice-of-complex-serial-parallel-mixed"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-theory-and-practice-of-complex-serial-parallel-mixed"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/research-on-theory-and-practice-of-complex-serial-parallel-mixed"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/research-on-theory-and-practice-of-complex-serial-parallel-mixed"}]]},"headers":[],"relativePath":"zh/research-on-theory-and-practice-of-complex-serial-parallel-mixed.md","filePath":"zh/page-NHHXhzWI123bEmz73RliaL.md"}'),i={name:"zh/research-on-theory-and-practice-of-complex-serial-parallel-mixed.md"};function t(p,e,n,c,s,d){return r(),l("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="复杂串并行混产理论与实践研究" tabindex="-1">复杂串并行混产理论与实践研究 <a class="header-anchor" href="#复杂串并行混产理论与实践研究" aria-label="Permalink to &quot;复杂串并行混产理论与实践研究&quot;">​</a></h1><blockquote><p>源页面 ID：<code>NHHXhzWI123bEmz73RliaL</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=NHHXhzWI123bEmz73RliaL" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><a href="/endfield-skydoc/zh/single-forge-heavy-xiranite-using-clock-signals">基于时钟信号的单烘炉重息壤方案</a></p><p><a href="/endfield-skydoc/zh/automatic-switching-for-reactions-with-multiple-raw-materials">复数原料反应的自动切换</a></p><p><a href="/endfield-skydoc/zh/xiragen-acridgen-in-series">息壤气\\酸气串行</a></p><p><span id="source-block-zXp8jky1KBHbdiXWYJEgbb"></span></p><h4 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h4><p>混产：同一台设备分时分槽执行多个不同配方，使得不需要多台机器实现省电。</p><p>串行：同一台机器轮流执行不同配方，使得小数分配的机器可以不浪费多余产能。</p><p>并行：反应池同时执行不同配方，使得多个反应池的配方同时进行，节约反应池数量。</p><p><span id="source-block-4A93oOQD9zx5Rpb882sG3p"></span></p><h4 id="自动清灰" tabindex="-1">自动清灰 <a class="header-anchor" href="#自动清灰" aria-label="Permalink to &quot;自动清灰&quot;">​</a></h4><p>机器的串行中，不同配方有可能原料数量不同，假定配方2a→A,2b→B，如果简单混带单个输入，在输入abbbb...序列时，机器里的东西无法满足任何一个配方的原料需求，而且再输入的东西和机器里的东西不同，也进不来，机器就会卡死。在传统情况下，此时需要玩家手动将这个物品掏出来，让之后的bbb正常输入，掏出这个a的操作就叫做清灰。</p><p>为了避免这个问题，我们可以在输入时就混带成特定比例，如aabbaabb...，但是对于某些配方，混带成这样过于复杂，还可能受到上下线相位变化影响，因此这个方案在很多时候不现实。</p><p>掏出a除了手动掏出来到外面，也可以再给它输入一个a，使其变成A自然离开机器，这就是自动清灰的核心思路了。</p><p>向机器输入会卡住的原料，使其反应消失来放行另一种原料。但是显然的，如果会卡住的原料a太多，那就相当于直接完全用于生产A了，没有达成串行的目的，为此，我们需要限制这个再输入的频率，只是偶尔才会输入，这样a反应就可以把原料反应完了，自然的切换为b反应，而此时b足够多，进一步阻止了再输入a的输入，使其在入口等着。</p><p><span class="mark-grey">言：a输入降速b输入不降速→切换反应为b反应，反之则切换为a反应，无非就是在做这件事情。</span></p><p>在介绍完核心思路后，就是一些实现上的问题了，对于哪些材料我们需要进行再输入？显然是在切换的两个配方中不一样，而且配方中该原料数量&gt;1的原料。不需要再输入的原料要如何输入？当然是能输入多少输入多少，只要不占据自动清灰必要的输入口即可。自动清灰看起来会严重影响速率，每次清灰都需要等待未知时长的再输入？当然是会的，为了解决这个问题，我们应该在其中一种需要再输入的原料即将耗尽时才切换，尽可能减少切换次数。再输入能不能混带输入？显然是不能的。</p></div>',1)])])}const f=a(i,[["render",t]]);export{b as __pageData,f as default};
